create table if not exists public.order_sequences (id bigint generated always as identity primary key,created_at timestamptz not null default now());create or replace function public.next_marksmen_order_id() returns text language plpgsql security definer as $$declare new_id bigint;begin insert into public.order_sequences default values returning id into new_id;return 'MM-'||lpad(new_id::text,6,'0');end;$$;grant execute on function public.next_marksmen_order_id() to anon,authenticated,service_role;create table if not exists public.custom_orders (id bigint generated always as identity primary key,order_id text unique not null,email text not null,payload jsonb not null,created_at timestamptz not null default now());alter table public.custom_orders enable row level security;